(1, 1, 0, 'http://127.0.0.1:8000/administrator/settings/update', 'settings', 'bulk_update', 'Update Settings', '{\"website_name\":\"TravelGenie\",\"short_title\":null,\"meta_title\":\"TravelGenie\",\"meta_description\":\"TravelGenie Description\",\"meta_keywords\":\"TravelGenie Keywords\",\"contact_email\":\"info@travelgenie.com\",\"contact_phone\":\"+917503840476\",\"site_address\":\"Ghaziabad, UttarPradesh\",\"facebook\":\"https:\\/\\/www.facebook.com\\/\",\"twitter\":\"https:\\/\\/x.com\\/\",\"instagram\":\"https:\\/\\/www.instagram.com\\/\",\"linkedin\":\"https:\\/\\/www.linkedin.com\\/\",\"youtube\":\"https:\\/\\/www.youtube.com\\/\",\"tiktok\":null,\"home_banner_size\":\"1200x500\",\"inner_banner_size\":\"1200x500\",\"other_social\":null}', '127.0.0.1', '2025-12-26 14:59:37'),
(2, 1, 12, 'http://127.0.0.1:8000/administrator/cms/12/update', 'cms_pages', 'Update CMS Page', 'Updated CMS page: About Us', '{\"title\":\"About Us\",\"slug\":\"about\",\"template\":\"about\",\"brief\":\"Not all those who wander are lost\\u201d ~ J.R.R. Tolkien\",\"heading\":null,\"description\":\"<p>These popular destinations have a lot to offer. Discover new places, unique experiences, and seamless travel planning with us.<\\/p>\",\"status\":\"1\",\"featured\":\"1\",\"sort_order\":\"1\"}', '127.0.0.1', '2025-12-27 16:27:44'),
