INSERT INTO `services` (`id`, `title`, `slug`, `brief`, `description`, `image`, `status`, `featured`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Web Development', 'web-development', 'Modern, scalable websites and web apps built on Laravel and React.', '<h3>What\'s Included</h3><ul><li>Custom Laravel APIs</li><li>React/Vue frontends</li><li>SSR and SEO optimization</li><li>Testing and CI/CD</li></ul><h3>Why Us</h3><p>We deliver clean architecture, strong performance, and maintainable code.</p>', NULL, 1, 1, 1, '2025-12-11 16:04:24', '2025-12-11 16:04:24'),
(2, 'Mobile App Development', 'mobile-app-development', 'Native and cross-platform apps with delightful UX.', '<h3>Capabilities</h3><ul><li>Android and iOS</li><li>React Native/Flutter</li><li>Push notifications</li><li>App Store/Play Store deployment</li></ul><h3>Process</h3><p>From prototyping to launch, we focus on speed and quality.</p>', NULL, 1, 1, 2, '2025-12-11 16:04:24', '2025-12-11 16:04:24'),
(3, 'UI/UX Design', 'ui-ux-design', 'User-centered design to boost engagement and conversions.', '<h3>Deliverables</h3><ul><li>Wireframes and prototypes</li><li>Design systems</li><li>Accessibility (WCAG)</li><li>Usability testing</li></ul><h3>Outcome</h3><p>Interfaces that are beautiful, consistent, and easy to use.</p>', NULL, 1, 1, 3, '2025-12-11 16:04:24', '2025-12-11 16:04:24'),
(4, 'Cloud & DevOps', 'cloud-devops', 'Infrastructure as code, observability, and cost-optimized deployments.', '<h3>Stack</h3><ul><li>AWS / Azure / GCP</li><li>Docker & Kubernetes</li><li>Terraform & Ansible</li><li>Monitoring & Logging</li></ul><h3>Benefits</h3><p>Resilient systems with automated deployments and scaling.</p>', NULL, 1, 0, 4, '2025-12-11 16:04:24', '2025-12-11 16:04:24'),
(5, 'E-commerce Development', 'ecommerce-development', 'High-conversion storefronts and custom e-commerce integrations.', '<h3>Features</h3><ul><li>Product catalog and filters</li><li>Checkout and payments</li><li>Order management</li><li>Analytics & growth tools</li></ul><h3>Integrations</h3><p>Stripe, PayPal, Razorpay, Shiprocket and more.</p>', NULL, 1, 0, 5, '2025-12-11 16:04:24', '2025-12-11 16:04:24'),
(6, 'SEO & Digital Marketing', 'seo-digital-marketing', 'Content strategy, technical SEO, and performance marketing.', '<h3>Services</h3><ul><li>SEO audit & fixes</li><li>Keyword research</li><li>Content & backlinks</li><li>Analytics & reporting</li></ul><h3>Result</h3><p>Organic growth and measurable ROI.</p>', NULL, 1, 0, 6, '2025-12-11 16:04:24', '2025-12-11 16:04:24');
